import sys,re
def apply(p,pairs):
    s=open(p,encoding='utf-8',newline='').read()
    for o,n in pairs:
        c=s.count(o)
        if c!=1: sys.exit(f'{p}: count {c} for {o[:90]!r}')
        s=s.replace(o,n)
    return s
