# blank line after each description heading line (title line followed directly by body text)
def blank_after_headings(s,lab):
    return re.sub(r'(?m)^(\*\*[^\n]*\*\* \*\('+lab+r'\. \d+[^\n]*\)\*)\n(?!\n)', r'\1\n\n', s)
sde=blank_after_headings(sde,'Nr'); sen=blank_after_headings(sen,'No')
open('README.md','w',encoding='utf-8',newline='').write(sde)
open('README.en.md','w',encoding='utf-8',newline='').write(sen)
print('ok', sde.count('\n'), sen.count('\n'))
